package Tv4.Controller;
import Tv4.View.ThoiKhoaBieuPage;import MainPage.View.Workspace;import MainPage.Controller.PageTasks;import Model.*;import Service.*;import Tv3.Controller.LopHocController;import java.time.*;import java.time.temporal.TemporalAdjusters;import java.util.*;
public class ThoiKhoaBieuController {
 private final ThoiKhoaBieuPage v;private final int b;private final String name;private LocalDate monday=LocalDate.now().with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));private List<LopHocModel> classes=List.of();private List<DanhMucModel> shifts=List.of();private List<ThoiKhoaBieuModel> rules=List.of();private List<BuoiHocModel> lessons=List.of();private boolean busy;
 private record Data(List<LopHocModel> classes,List<DanhMucModel> shifts,List<ThoiKhoaBieuModel> rules,List<BuoiHocModel> lessons){}
 public ThoiKhoaBieuController(ThoiKhoaBieuPage v,int b){this(v,b,"Cơ sở #"+b);}
 public ThoiKhoaBieuController(ThoiKhoaBieuPage v,int b,String name){this.v=v;this.b=b;this.name=name;v.action("← Tuần trước",()->{monday=monday.minusWeeks(1);render();});v.action("Tuần này",()->{monday=LocalDate.now().with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));render();});v.action("Tuần sau →",()->{monday=monday.plusWeeks(1);render();});v.action("+ Thêm lớp",()->LopHocController.openAdd(v,b,()->load(false)));v.action("Tải lại",()->load(true));v.classMenu(i->{int id=v.selectedClass();if(id<=0)return;if(i==0)LopHocController.openDetails(v,b,id);else LopHocController.delete(v,b,id,()->load(false));});load(false);}
 private void load(boolean force){if(busy)return;busy=true;v.status("Đang tải...");PageTasks.run(v,()->{try{var l=new LopHocService();var c=new DanhMucService();var t=new ThoiKhoaBieuService();var s=new BuoiHocService();return new Data(force?l.reload(b):l.selectAll(b),(force?c.reload(b):c.selectAll(b)).stream().filter(x->"CA_HOC".equals(x.getNhomDanhMuc())).toList(),force?t.reload(b):t.selectAll(b),force?s.reload(b):s.selectAll(b));}finally{javax.swing.SwingUtilities.invokeLater(()->busy=false);}},d->{classes=d.classes;shifts=d.shifts;rules=d.rules;lessons=d.lessons;v.classes(classes.stream().filter(x->"DANG_MO".equals(x.getTrangThai())).map(x->new ThoiKhoaBieuPage.ClassItem(x.getMaLop(),x.getTenLop())).toList());render();});}
 private String label(int id){return classes.stream().filter(x->x.getMaLop()==id).map(LopHocModel::getTenLop).findFirst().orElse("Lớp #"+id);}
 @SuppressWarnings("unchecked") private void render(){v.title("THỜI KHÓA BIỂU — "+name,"Tuần "+monday+" → "+monday.plusDays(5));String[] days=new String[6];for(int i=0;i<6;i++)days[i]="Thứ "+(i+2)+" | "+monday.plusDays(i);String[] names=new String[shifts.size()];int[] ids=new int[names.length];List<ThoiKhoaBieuPage.SlotItem>[][] cells=(List<ThoiKhoaBieuPage.SlotItem>[][])new List[names.length][6];for(int r=0;r<names.length;r++){var ca=shifts.get(r);ids[r]=ca.getMaDanhMuc();names[r]="<html>"+ca.getTenDanhMuc()+"<br>"+PageTasks.field(ca.getCauHinh(),"GioBatDau")+" - "+PageTasks.field(ca.getCauHinh(),"GioKetThuc")+"</html>";for(int c=0;c<6;c++){LocalDate date=monday.plusDays(c);var a=new ArrayList<ThoiKhoaBieuPage.SlotItem>();Set<Integer> seen=new HashSet<>();for(var t:rules){if(!t.isTrangThai()||t.getMaCaHoc()!=ids[r]||t.getThuTrongTuan()!=date.getDayOfWeek().getValue()||date.isBefore(t.getTuNgay())||t.getDenNgay()!=null&&date.isAfter(t.getDenNgay()))continue;var actual=lessons.stream().filter(x->x.getMaLop()==t.getMaLop()&&x.getMaCaHoc()==t.getMaCaHoc()&&date.equals(x.getNgayHoc())).findFirst().orElse(null);if(actual!=null)seen.add(actual.getMaBuoiHoc());a.add(new ThoiKhoaBieuPage.SlotItem(t.getMaThoiKhoaBieu(),actual==null?0:actual.getMaBuoiHoc(),t.getMaLop(),label(t.getMaLop())+" · "+(actual==null?"Lịch lặp":actual.getTrangThai())));}for(var l:lessons)if(l.getMaCaHoc()==ids[r]&&date.equals(l.getNgayHoc())&&!seen.contains(l.getMaBuoiHoc()))a.add(new ThoiKhoaBieuPage.SlotItem(0,l.getMaBuoiHoc(),l.getMaLop(),label(l.getMaLop())+" · "+l.getTrangThai()));cells[r][c]=a;}}v.grid(days,names,ids,cells,this::place,this::menu);v.status(shifts.isEmpty()?"Chưa có CA_HOC trong DanhMuc; cần thiết lập ca học.":"Kéo lớp vào ô để xác nhận lịch lặp; chuột phải để tạo/kích hoạt hoặc hủy buổi.");}
 private void place(int lop,int day,int ca){LocalDate date=monday.plusDays(day);if(!Workspace.confirm(v,"Xếp lớp "+label(lop)+" vào ca #"+ca+" từ "+date+" (lặp hằng tuần)?"))return;PageTasks.run(v,()->{var svc=new ThoiKhoaBieuService();var l=new LopHocService().getByMaLop(b,lop);PageTasks.require(l!=null&&"DANG_MO".equals(l.getTrangThai()),"Lớp không hoạt động");PageTasks.require(!date.isBefore(l.getNgayBatDau())&&(l.getNgayKetThuc()==null||!date.isAfter(l.getNgayKetThuc())),"Ngày ngoài thời gian lớp");var all=svc.reload(b);PageTasks.require(all.stream().noneMatch(x->x.isTrangThai()&&x.getMaLop()==lop&&x.getMaCaHoc()==ca&&x.getThuTrongTuan()==date.getDayOfWeek().getValue()&&(x.getDenNgay()==null||!x.getDenNgay().isBefore(date))&&(l.getNgayKetThuc()==null||!x.getTuNgay().isAfter(l.getNgayKetThuc()))),"Đã có lịch trùng");ThoiKhoaBieuModel t=new ThoiKhoaBieuModel();t.setMaLop(lop);t.setMaCaHoc(ca);t.setThuTrongTuan(date.getDayOfWeek().getValue());t.setTuNgay(date);t.setDenNgay(l.getNgayKetThuc());PageTasks.require(svc.insert(b,t),"Không lưu được lịch");return true;},x->load(false));}
 private void menu(ThoiKhoaBieuPage.SlotItem item,int day,int ca,int action){LocalDate date=monday.plusDays(day);if(action==0){LopHocController.openDetails(v,b,item.lop());return;}if(action==1){if(item.lesson()>0){if(!Workspace.confirm(v,"Kích hoạt buổi #"+item.lesson()+"?"))return;PageTasks.actor(v,b,actor->PageTasks.run(v,()->{var s=new BuoiHocService();var l=s.getByMaBuoiHoc(b,item.lesson());PageTasks.require(l!=null&&"DU_KIEN".equals(l.getTrangThai()),"Chỉ kích hoạt buổi dự kiến");l.setTrangThai("DA_KICH_HOAT");l.setMaNguoiKichHoat(actor);l.setNgayKichHoat(LocalDateTime.now(ZoneOffset.UTC));PageTasks.require(s.update(b,l),"Không kích hoạt được");return true;},r->load(false)));}else if(Workspace.confirm(v,"Tạo buổi học dự kiến ngày "+date+"?")){PageTasks.run(v,()->{var shift=new DanhMucService().getByMaDanhMuc(b,ca);var cls=new LopHocService().getByMaLop(b,item.lop());PageTasks.require(shift!=null&&cls!=null,"Thiếu ca/lớp");BuoiHocModel l=new BuoiHocModel();l.setMaLop(item.lop());l.setMaThoiKhoaBieu(item.rule()>0?item.rule():null);l.setNgayHoc(date);l.setMaCaHoc(ca);l.setGioBatDau(LocalTime.parse(PageTasks.field(shift.getCauHinh(),"GioBatDau")));l.setGioKetThuc(LocalTime.parse(PageTasks.field(shift.getCauHinh(),"GioKetThuc")));l.setMaGiaoVien(cls.getMaGiaoVien());PageTasks.require(new BuoiHocService().insert(b,l),"Không tạo được buổi");return true;},r->load(false));}return;}if(action==2&&item.lesson()>0){if(!Workspace.confirm(v,"Hủy buổi học? Không xóa lịch sử."))return;PageTasks.run(v,()->{var ds=new DiemDanhService();PageTasks.require(ds.getByMaBuoiHoc(b,item.lesson()).isEmpty(),"Buổi có điểm danh/học thử; chưa thể hủy an toàn");var s=new BuoiHocService();var l=s.getByMaBuoiHoc(b,item.lesson());PageTasks.require(l!=null&&!"HOAN_THANH".equals(l.getTrangThai()),"Không hủy buổi đã hoàn thành");l.setTrangThai("HUY");PageTasks.require(s.update(b,l),"Không hủy được");return true;},r->load(false));}if(action==3&&item.rule()>0&&Workspace.confirm(v,"Ngừng lịch lặp từ "+date+"? Các buổi đã tạo được giữ nguyên.")){PageTasks.run(v,()->{var s=new ThoiKhoaBieuService();var t=s.getByMaThoiKhoaBieu(b,item.rule());PageTasks.require(t!=null,"Không tìm thấy lịch");if(date.isAfter(t.getTuNgay()))t.setDenNgay(date.minusDays(1));else t.setTrangThai(false);PageTasks.require(s.update(b,t),"Không lưu được lịch");return true;},r->load(false));}}
}
